  expect_equal(.run("parse_expr(\"3.2[3]\")"), "97/30")
  expect_equal(.run("parse_expr(\"1.3[12]\")"), "433/330")
  expect_equal(.run("parse_expr(\"1 + 3.[3]\")"), "13/3")
  expect_equal(.run("parse_expr(\"1 + .0[3]\")"), "31/30")
  expect_equal(.run("parse_expr(\"1 + 3.2[3]\")"), "127/30")
  expect_equal(.run("parse_expr(\".[0011]\")"), "1/909")
  expect_equal(.run("parse_expr(\"0.1[00102] + 1\")"), "366697/333330")
  expect_equal(.run("parse_expr(\"1.[0191]\")"), "10190/9999")
  expect_equal(.run("parse_expr(\"10!\")"), "3628800")
  expect_equal(.run("parse_expr(\"-(2)\")"), "-2")
  expect_equal(.run("parse_expr(\"[-1, -2, 3]\")"), "[-1, -2, 3]")
  expect_equal(.run("parse_expr(\"Symbol(\\\"x\\\").free_symbols\")"), "{x}")
  expect_equal(.run("parse_expr(\"S('S(3).n(n=3)')\")"), "3.00")
  expect_equal(.run("parse_expr(\"factorint(12, visual=True)\")"), "2^2*3^1")
  expect_equal(.run("parse_expr(\"Limit(sin(x), x, 0, dir=\\\"-\\\")\")"), "Limit(sin(x), x, 0, dir='-')")
  expect_equal(.err("parse_expr(\"1[1]\")"), "'One' object is not subscriptable")
  expect_equal(.err("parse_expr(\".1e1[1]\")"), "'Float' object is not subscriptable")
  expect_equal(.err("parse_expr(\"0x1[1]\")"), "'One' object is not subscriptable")
