  expect_equal(.err("parse_expr(\"1.1[1 + 1]\")"), "'Float' object is not subscriptable")
  expect_equal(.err("parse_expr(\"0.1[[1]]\")"), "'Float' object is not subscriptable")
  expect_equal(.err("parse_expr(\"0x1.1[1]\")"), "'One' object is not callable")
  expect_equal(.err("parse_expr(\"0.1[\")"), "('unexpected EOF in multi-line statement', (1, 0))")
  expect_equal(.err("parse_expr(\"0.1[1\")"), "('unexpected EOF in multi-line statement', (1, 0))")
  expect_equal(.err("parse_expr(\"0.1[]\")"), "invalid syntax (<string>, line 1)")
  expect_equal(.run("parse_expr(\".[1]\")"), "1/9")
  expect_equal(.run("parse_expr(\"1 + .[1]\")"), "10/9")
  expect_equal(.err("parse_expr(\"(()\")"), "('unexpected EOF in multi-line statement', (1, 0))")
