  expect_equal(.run("parse_expr(\"f(x)\")"), "f(x)")
  expect_equal(.run("parse_expr(\"xy\")"), "xy")
  expect_equal(.run("parse_expr(\"\\U{3b1}\")"), "α")
  expect_equal(.run("parse_expr(\"123_456\")"), "123456")
