  expect_equal(.run("parse_expr(\"(factorial)\", transformations = c(standard_transformations, list(convert_xor, implicit_multiplication_application)))"), "factorial")
  expect_equal(.run("parse_expr(\"tan 3x\", transformations = c(standard_transformations, list(convert_xor, implicit_multiplication_application)))"), "tan(3*x)")
  expect_equal(.run("parse_expr(\"tan(3*x)\", transformations = c(standard_transformations, list(convert_xor)))"), "tan(3*x)")
  expect_equal(.run("parse_expr(\"sin^2(3*E^(x))\", transformations = c(standard_transformations, list(convert_xor, implicit_multiplication_application)))"), "sin(3*exp(x))^2")
  expect_equal(.run("parse_expr(\"sin(3*E**(x))**2\", transformations = c(standard_transformations, list(convert_xor)))"), "sin(3*exp(x))^2")
  expect_equal(.run("parse_expr(\"sin**2(E^(3x))\", transformations = c(standard_transformations, list(convert_xor, implicit_multiplication_application)))"), "sin(exp(3*x))^2")
  expect_equal(.run("parse_expr(\"sin(E**(3*x))**2\", transformations = c(standard_transformations, list(convert_xor)))"), "sin(exp(3*x))^2")
  expect_equal(.run("parse_expr(\"sin^2 (3x*E^(x))\", transformations = c(standard_transformations, list(convert_xor, implicit_multiplication_application)))"), "sin(3*x*exp(x))^2")
  expect_equal(.run("parse_expr(\"sin(3*x*E^x)**2\", transformations = c(standard_transformations, list(convert_xor)))"), "sin(3*x*exp(x))^2")
  expect_equal(.run("parse_expr(\"pi sin x\", transformations = c(standard_transformations, list(convert_xor, implicit_multiplication_application)))"), "pi*sin(x)")
  expect_equal(.run("parse_expr(\"x.is_polynomial(x)\", transformations = c(standard_transformations, list(implicit_multiplication)))"), "True")
  expect_equal(.run("parse_expr(\"(exp(x) / (1 + exp(2x))).subs(exp(x), u)\", transformations = c(standard_transformations, list(implicit_multiplication)))"), "u/(u^2 + 1)")
})
